// Procesar mensaje de Telegram o WhatsApp
// Detectar si viene del webhook de WhatsApp o del trigger de Telegram
let telegramMessage = null;
let messageSource = 'telegram'; // Por defecto Telegram

// PRIMERO: Verificar si viene del Telegram Trigger (tiene update_id)
try {
  const telegramData = items[0].json;
  if (telegramData && telegramData.update_id !== undefined && telegramData.message) {
    // Viene de Telegram Trigger
    telegramMessage = telegramData.message;
    messageSource = 'telegram';
    console.log('📱 Mensaje detectado desde Telegram Trigger');
  }
} catch (e) {
  console.log('⚠️ No se pudo leer de Telegram Trigger:', e.message);
}

// SEGUNDO: Si no viene de Telegram, intentar leer del nodo Code (WhatsApp)
if (!telegramMessage) {
  try {
    const codeData = $node['Code']?.json;
    if (codeData && codeData.message) {
      telegramMessage = codeData.message;
      messageSource = 'whatsapp';
      console.log('📱 Mensaje detectado desde WhatsApp (nodo Code)');
    }
  } catch (e) {
    console.log('⚠️ No se pudo leer de Code:', e.message);
  }
}

// TERCERO: Intentar leer de items[0] si tiene formato de Telegram (viene de Code)
if (!telegramMessage && items && items.length > 0 && items[0].json) {
  const itemData = items[0].json;

  // Si tiene el formato de Telegram pero NO tiene update_id (viene de Code/WhatsApp)
  if (itemData.message && itemData.update_id === undefined) {
    telegramMessage = itemData.message;
    messageSource = 'whatsapp';
    console.log('📱 Mensaje detectado desde WhatsApp (formateado desde Code)');
  }
}

if (!telegramMessage) {
  console.error('❌ No se pudo obtener el mensaje de ninguna fuente');
  console.error('📥 Items recibidos:', JSON.stringify(items, null, 2));
  throw new Error('No se pudo obtener el mensaje de ninguna fuente');
}

const chatId = telegramMessage.chat?.id || telegramMessage.chat_id;
const userId = telegramMessage.from?.id || telegramMessage.user_id;
const userName = telegramMessage.from?.first_name || telegramMessage.user_name || 'Usuario';
const userLastName = telegramMessage.from?.last_name || '';
let messageText = telegramMessage.text || '';
const messageId = telegramMessage.message_id;

// DETECTAR UBICACIÓN GPS
let hasLocation = false;
let latitude = null;
let longitude = null;

if (telegramMessage.location && telegramMessage.location.latitude && telegramMessage.location.longitude) {
  hasLocation = true;
  latitude = telegramMessage.location.latitude;
  longitude = telegramMessage.location.longitude;
  // Generar mensaje automático con las coordenadas para fichaje
  messageText = `Fichar ubicacion: ${latitude}, ${longitude}`;
  console.log('📍 UBICACIÓN DETECTADA:');
  console.log('   Latitud:', latitude);
  console.log('   Longitud:', longitude);
  console.log('   Mensaje generado:', messageText);
}

console.log('📱 Mensaje recibido desde:', messageSource.toUpperCase());
console.log('   Chat ID:', chatId);
console.log('   Usuario:', userName, userLastName);
console.log('   Mensaje:', messageText);
console.log('   Tiene ubicación:', hasLocation);

// Comandos especiales
if (messageText.startsWith('/start')) {
  return [{
    json: {
      chatId: chatId,
      isCommand: true,
      commandType: 'start',
      directResponse: '👋 ¡Hola! Soy el asistente de IA de Odoo.\n\nPuedo ayudarte con:\n\n📋 Crear contactos, productos y oportunidades\n💰 Gestionar pedidos de venta y compras\n📦 Mover inventario entre almacenes\n📧 Enviar recordatorios de pago\n✅ Gestionar tareas y proyectos\n📍 Fichar entrada/salida con ubicación\n\n¿En qué puedo ayudarte hoy?',
      messageSource: messageSource
    }
  }];
}

if (messageText.startsWith('/help')) {
  return [{
    json: {
      chatId: chatId,
      isCommand: true,
      commandType: 'help',
      directResponse: '🆘 **Ayuda del Bot**\n\n**Comandos:**\n/start - Iniciar bot\n/help - Ver esta ayuda\n\n**Ejemplos de uso:**\n\n📋 "Crea un contacto llamado Juan Pérez"\n💰 "Crea un presupuesto para el cliente ABC"\n📦 "Mueve 10 guantes de WH/Stock a AV/Stock"\n📧 "Envía recordatorio de pago a todos"\n✅ "Crea una tarea: Revisar facturas"\n🔄 "Repite la última venta a Jorge"\n📍 Envía tu ubicación para fichar',
      messageSource: messageSource
    }
  }];
}

return [{
  json: {
    chatId: chatId,
    userId: userId,
    userName: userName + ' ' + userLastName,
    messageText: messageText,
    messageId: messageId,
    timestamp: new Date().toISOString(),
    isCommand: false,
    messageSource: messageSource,
    hasLocation: hasLocation,
    latitude: latitude,
    longitude: longitude
  }
}];

