// Procesar respuesta de creación de mensaje (JSON-RPC)
// JSON-RPC devuelve { result: ID } o { error: ... }
const messageResponse = items[0].json;
const channelData = $node['Prepare Channel Data'].json;

let messageId = null;

if (messageResponse && messageResponse.result) {
  let result = messageResponse.result;

  // Si result es un array, tomar el primer elemento
  if (Array.isArray(result)) {
    messageId = result[0];
    console.log('📦 Resultado es array, tomando primer elemento:', messageId);
  } 
  // Si result es un objeto con 'id', extraerlo
  else if (typeof result === 'object' && result.id) {
    messageId = result.id;
    console.log('📦 Resultado es objeto, extrayendo ID:', messageId);
  }
  // Si result es un número, usarlo directamente
  else if (typeof result === 'number') {
    messageId = result;
    console.log('📦 Resultado es número:', messageId);
  }
  else {
    messageId = result;
    console.log('📦 Resultado sin procesar:', result);
  }

  console.log('✅ Mensaje enviado al canal:', channelData.channelName);
  console.log('   ID del mensaje:', messageId, '(tipo:', typeof messageId + ')');
  console.log('⏳ Esperando respuesta de la IA de Odoo...');
} else if (messageResponse && messageResponse.error) {
  console.error('❌ Error al enviar mensaje:', messageResponse.error);
  throw new Error('Error al enviar mensaje: ' + JSON.stringify(messageResponse.error));
} else {
  console.error('❌ Respuesta inesperada:', messageResponse);
  throw new Error('Respuesta inesperada del servidor');
}

// Asegurarse de que messageId es un número entero
messageId = parseInt(messageId);

if (isNaN(messageId)) {
  throw new Error('No se pudo obtener un ID de mensaje válido');
}

// Intentar obtener datos de Combinar Usuario + Mensaje si están disponibles
let odooUserRef = null;
let telegramUserId = null;
let telegramChatId = null;
let latitude = null;
let longitude = null;

try {
  const combinacionData = $('Combinar Usuario + Mensaje').item?.json;
  if (combinacionData) {
    odooUserRef = combinacionData.odoo_user || null;
    telegramUserId = combinacionData.user_id || null;
    telegramChatId = combinacionData.chat_id || null;
    latitude = combinacionData.latitude || null;
    longitude = combinacionData.longitude || null;
  }
} catch (e) {
  // El nodo no se ejecutó, usar valores null
}

return [{
  json: {
    mail_message_id: messageId,
    channel_id: channelData.channelId,
    channel_name: channelData.channelName,
    messageText: channelData.messageText,
    chatId: channelData.chatId,
    uid: channelData.uid,
    db: channelData.db,
    timestamp_sent: new Date().toISOString(),
    messageSource: channelData.messageSource || 'telegram',
    odoo_user_ref: odooUserRef,
    telegram_user_id: telegramUserId,
    telegram_chat_id: telegramChatId,
    latitude: latitude,
    longitude: longitude
  }
}];

