// Procesar respuesta del AI desde los mensajes del canal (JSON-RPC)
// JSON-RPC devuelve { result: [...] } con los mensajes
const messagesResponse = items[0].json;
const messageData = $node['Process Message ID'].json;

let aiMessage = '';
let hasError = false;

console.log('📥 Respuesta JSON-RPC:', JSON.stringify(messagesResponse, null, 2));

try {
  if (messagesResponse && messagesResponse.error) {
    hasError = true;
    aiMessage = '❌ Error al obtener respuesta del AI: ' + JSON.stringify(messagesResponse.error);
    console.error('Error en Get AI Response:', messagesResponse.error);
  }
  else if (messagesResponse && messagesResponse.result && Array.isArray(messagesResponse.result)) {
    const messages = messagesResponse.result;
    const userMessageId = messageData.mail_message_id;

    console.log('📊 Mensajes recibidos:', messages.length);
    console.log('🔍 Buscando mensaje después del ID:', userMessageId);

    // Buscar el primer mensaje del AI (author_id = 7) que sea más reciente que el del usuario
    for (const msg of messages) {
      // Verificar que sea del AI (author_id = 7) y más reciente que el mensaje del usuario
      if (msg.author_id && msg.author_id[0] === 7 && msg.id > userMessageId) {
        // Extraer el texto del body (puede tener HTML)
        let bodyText = msg.body || '';
        // Limpiar HTML tags
        bodyText = bodyText.replace(/<[^>]*>/g, '').trim();

        if (bodyText && bodyText.length > 0) {
          aiMessage = bodyText;
          console.log('✅ Respuesta del AI encontrada (ID: ' + msg.id + '):', aiMessage.substring(0, 100));
          break;
        }
      }
    }

    // Si no encontramos respuesta, usar el último mensaje del AI
    if (!aiMessage && messages.length > 0) {
      for (const msg of messages) {
        if (msg.author_id && msg.author_id[0] === 7 && msg.body) {
          aiMessage = msg.body.replace(/<[^>]*>/g, '').trim();
          console.log('⚠️ Usando último mensaje del AI como respuesta (ID: ' + msg.id + '):', aiMessage.substring(0, 100));
          break;
        }
      }
    }
  }

  if (!aiMessage) {
    hasError = true;
    aiMessage = '⏳ El AI aún está procesando tu mensaje. Por favor espera unos segundos y vuelve a intentar.';
    console.warn('⚠️ No se encontró respuesta del AI');
  }
} catch (error) {
  hasError = true;
  aiMessage = '❌ Error al procesar respuesta: ' + error.message;
  console.error('Error en Process AI Response:', error);
}

// Limpiar HTML tags adicionales
aiMessage = aiMessage.replace(/<[^>]*>/g, '').trim();

console.log('📤 Respuesta del AI a enviar:', aiMessage.substring(0, 200));

// Obtener el origen del mensaje desde Process Telegram Message
let messageSource = 'telegram';
try {
  const processMessageData = $node['Process Telegram Message'].json;
  messageSource = processMessageData.messageSource || 'telegram';
  console.log('📱 Origen del mensaje detectado:', messageSource);
} catch (e) {
  console.warn('⚠️ No se pudo obtener messageSource, usando Telegram por defecto');
}

return [{
  json: {
    chatId: messageData.chatId,
    aiMessage: aiMessage,
    hasError: hasError,
    timestamp: new Date().toISOString(),
    messageSource: messageSource
  }
}];

// Extraer UID del login
const authResponse = items[0].json;

let uid = null;

if (authResponse && authResponse.result) {
  uid = authResponse.result;
  console.log('✅ Login exitoso, UID:', uid);
} else if (authResponse && authResponse.error) {
  console.error('❌ Error en login:', authResponse.error);
  throw new Error('Error de autenticación: ' + JSON.stringify(authResponse.error));
} else {
  console.error('❌ Respuesta inesperada del login:', authResponse);
  throw new Error('Respuesta inesperada del servidor');
}

// Verificar si hay datos de transcripción (cuando viene de audio)
let messageText = null;
let chatId = null;
let userId = null;
let userName = null;
let timestamp = null;
let esAudio = false;

// Intentar leer datos de transcripción si existen (cuando viene de audio)
try {
  const transcripcionData = $node['Actualizar Datos Transcripción']?.json;
  if (transcripcionData && transcripcionData.audio_transcrito) {
    // Usar el mensaje transcrito (sin tildes, normalizado para el agente)
    messageText = transcripcionData.mensaje_usuario || transcripcionData.transcripcion_original;
    chatId = transcripcionData.chat_id;
    userId = transcripcionData.user_id;
    userName = transcripcionData.user_name;
    timestamp = transcripcionData.timestamp;
    esAudio = true;
    console.log('🎤 Usando datos de transcripción de audio:');
    console.log('   Mensaje transcrito:', messageText);
    console.log('   Chat ID:', chatId);
  }
} catch (e) {
  console.log('⚠️ No se pudieron leer datos de transcripción:', e.message);
}

// Si no hay datos de transcripción, usar datos de Process Telegram Message
let messageSource = 'telegram';
if (!messageText) {
  try {
    const messageData = $node['Process Telegram Message'].json;
    messageText = messageData.messageText;
    chatId = messageData.chatId;
    userId = messageData.userId;
    userName = messageData.userName;
    timestamp = messageData.timestamp;
    messageSource = messageData.messageSource || 'telegram';
    console.log('📝 Usando mensaje de texto normal:', messageText);
    console.log('📱 Origen del mensaje:', messageSource);
  } catch (e) {
    console.error('❌ No se pudieron leer datos de Process Telegram Message:', e.message);
    throw new Error('No se pudieron obtener los datos del mensaje');
  }
}

// 🔴 NUEVO: intentar leer datos de fichaje (odoo_user) si existen
let odooUser = null;
let tieneOdooUser = false;

try {
  const datosFichaje = $node['Combinar Usuario + Mensaje'].json;
  if (datosFichaje && datosFichaje.tiene_ubicacion === true && datosFichaje.tiene_odoo_user === true) {
    odooUser = datosFichaje.odoo_user || null;
    tieneOdooUser = true;

    // Opcional: usar el mensaje_usuario que ya generaste en Extraer Datos
    if (datosFichaje.mensaje_usuario) {
      messageText = datosFichaje.mensaje_usuario;
      console.log('📍 Overriding messageText desde Combinar Usuario + Mensaje:', messageText);
    }

    console.log('👤 odoo_user detectado para fichaje:', odooUser);
  } else {
    console.log('ℹ️ Combinar Usuario + Mensaje no indica fichaje con odoo_user.');
  }
} catch (e) {
  console.log('ℹ️ Combinar Usuario + Mensaje no disponible en este flujo (no es fichaje por ubicación).');
}

return [{
  json: {
    uid: uid,
    messageText: messageText,
    chatId: chatId,
    userId: userId,
    userName: userName,
    timestamp: timestamp,
    db: 'mchecagoshawk-ia19new-main-27686188',
    esAudio: esAudio,
    messageSource: messageSource,
    // 🔴 NUEVO: datos del usuario de Odoo
    odoo_user: odooUser,
    tiene_odoo_user: tieneOdooUser
  }
}];

// Procesar resultado de búsqueda de canal AI
const searchResponse = items[0].json;
const userData = $node['Extract UID from Login'].json;

console.log('🔍 Respuesta búsqueda canal:', JSON.stringify(searchResponse, null, 2));
console.log('👤 UserData recibido:', JSON.stringify(userData, null, 2));

// Verificar que userData tenga uid y db
if (!userData || !userData.uid || !userData.db) {
  console.error('❌ UserData incompleto:', userData);
  throw new Error('Faltan datos de autenticación (uid o db)');
}

let channelId = null;
let channelName = 'Ask AI';
let aiAgentName = 'Ask AI'; // Valor por defecto
let needsCreation = false;

// Verificar si hay error en la respuesta
if (searchResponse && searchResponse.error) {
  console.error('❌ Error en búsqueda:', searchResponse.error);
  throw new Error('Error al buscar canal AI: ' + JSON.stringify(searchResponse.error.data.message));
}

// Verificar resultado
if (searchResponse && searchResponse.result && Array.isArray(searchResponse.result)) {
  console.log('📊 Total canales ai_chat encontrados:', searchResponse.result.length);

  if (searchResponse.result.length > 0) {
    const channel = searchResponse.result[0];
    channelId = channel.id;
    channelName = channel.name;

    // No intentamos leer ai_agent_id por permisos
    // Usamos el nombre del canal como referencia
    aiAgentName = channelName;

    console.log('✅ Canal AI encontrado:', channelName, '(ID:', channelId + ')');
    console.log('🤖 Usando canal de tipo ai_chat');
    needsCreation = false;
  } else {
    // No hay canales de tipo ai_chat - necesitamos crearlo
    console.warn('⚠️ No se encontró ningún canal de tipo ai_chat');
    console.log('🔧 Se creará automáticamente usando el AI Agent');
    needsCreation = true;
  }
} else {
  console.error('❌ Respuesta inesperada:', searchResponse);
  throw new Error('Respuesta inesperada al buscar canal AI');
}

// Asegurar que todos los campos necesarios estén presentes
const resultData = {
  uid: userData.uid,
  db: userData.db,
  messageText: userData.messageText,
  chatId: userData.chatId,
  userId: userData.userId,
  userName: userData.userName,
  timestamp: userData.timestamp,
  channelId: channelId,
  channelName: channelName,
  aiAgentName: aiAgentName,
  needsCreation: needsCreation
};

console.log('📦 ResultData preparado:', JSON.stringify(resultData, null, 2));

// Devolver dos salidas: [0] para crear canal, [1] para usar canal existente
if (needsCreation) {
  return [[{ json: resultData }], []];
} else {
  return [[], [{ json: resultData }]];
}

// Pasar datos de Find AI Channel explícitamente
// Este nodo asegura que los datos se propaguen correctamente
console.log('📥 Items recibidos:', JSON.stringify(items, null, 2));
console.log('📥 Total items:', items ? items.length : 0);

let inputData = null;

// Intentar leer de items[0] primero
if (items && items.length > 0) {
  const firstItem = items[0];
  console.log('📦 Primer item completo:', JSON.stringify(firstItem, null, 2));

  if (firstItem && firstItem.json) {
    inputData = firstItem.json;
    console.log('✅ Datos obtenidos de items[0].json:', JSON.stringify(inputData, null, 2));
  } else if (firstItem && typeof firstItem === 'object') {
    // Si el item es directamente el objeto de datos
    inputData = firstItem;
    console.log('✅ Datos obtenidos directamente de items[0]:', JSON.stringify(inputData, null, 2));
  }
}

// Si no funciona, intentar leer directamente de Find AI Channel
if (!inputData || !inputData.uid || !inputData.db) {
  console.warn('⚠️ Datos no disponibles en items, intentando leer de Find AI Channel...');
  try {
    const findChannelData = $node['Find AI Channel'].json;
    console.log('📥 Datos de Find AI Channel:', JSON.stringify(findChannelData, null, 2));
    if (findChannelData && findChannelData.uid && findChannelData.db) {
      inputData = findChannelData;
      console.log('✅ Datos obtenidos de Find AI Channel:', JSON.stringify(inputData, null, 2));
    }
  } catch (e) {
    console.warn('⚠️ No se pudo leer de Find AI Channel:', e.message);
  }
}

// Si aún no tenemos datos, intentar de Extract UID from Login
if (!inputData || !inputData.uid || !inputData.db) {
  console.warn('⚠️ Intentando leer de Extract UID from Login...');
  try {
    const extractData = $node['Extract UID from Login'].json;
    console.log('📥 Datos de Extract UID from Login:', JSON.stringify(extractData, null, 2));
    if (extractData && extractData.uid && extractData.db) {
      inputData = {
        ...extractData,
        channelId: null,
        channelName: 'Ask AI',
        aiAgentName: 'Ask AI',
        needsCreation: true
      };
      console.log('✅ Datos obtenidos de Extract UID from Login:', JSON.stringify(inputData, null, 2));
    }
  } catch (e) {
    console.warn('⚠️ No se pudo leer de Extract UID from Login:', e.message);
  }
}

console.log('📤 Datos finales a pasar:', JSON.stringify(inputData, null, 2));

// Validar que tenemos los datos necesarios
if (!inputData || !inputData.uid || !inputData.db) {
  console.error('❌ Datos incompletos recibidos:', inputData);
  console.error('❌ Items recibidos:', JSON.stringify(items, null, 2));
  throw new Error('Faltan datos de autenticación (uid=' + (inputData?.uid || 'null') + ', db=' + (inputData?.db || 'null') + ')');
}

// Pasar los datos tal cual
return [{ json: inputData }];

// Combinar datos de Pass Channel Data con respuesta de Get Ask AI Agent
const agentResponse = items[0].json;

// Leer datos de Pass Channel Data (que viene de Find AI Channel)
const inputData = $node['Pass Channel Data'].json;

console.log('🤖 Respuesta Get Ask AI Agent:', JSON.stringify(agentResponse, null, 2));
console.log('📥 Datos de entrada desde Pass Channel Data:', JSON.stringify(inputData, null, 2));

// Validar que tenemos los datos necesarios
if (!inputData || !inputData.uid || !inputData.db) {
  console.error('❌ Datos incompletos:', inputData);
  throw new Error('Faltan datos de autenticación (uid=' + (inputData?.uid || 'null') + ', db=' + (inputData?.db || 'null') + ')');
}

// search_read devuelve { result: [...] }
let agentId = null;
let agentName = null;
let agentPartnerId = null;

if (agentResponse && agentResponse.result && Array.isArray(agentResponse.result) && agentResponse.result.length > 0) {
  const agent = agentResponse.result[0];
  agentId = agent.id;
  agentName = agent.name;
  agentPartnerId = agent.partner_id && agent.partner_id[0] ? agent.partner_id[0] : null;
  console.log('✅ AI Agent encontrado:', agentName, '(ID:', agentId + ')');
} else if (agentResponse && agentResponse.error) {
  console.error('❌ Error al buscar AI Agent:', agentResponse.error);
  throw new Error('Error al buscar AI Agent: ' + JSON.stringify(agentResponse.error.data.message));
} else {
  console.error('❌ No se encontró ningún AI Agent Ask AI');
  throw new Error('No se encontró ningún AI Agent configurado como Ask AI');
}

// Combinar datos de entrada con respuesta
return [{
  json: {
    ...inputData,
    agent_id: agentId,
    agent_name: agentName,
    agent_partner_id: agentPartnerId,
    agent_response: agentResponse
  }
