// Función para extraer datos de contacto
function extractContactInfo(contacts) {
  if (contacts && contacts[0]) {
    const contact = contacts[0];
    return {
      userName: contact.profile?.name || contact.wa_id || 'Usuario WhatsApp',
      wa_id: contact.wa_id
    };
  }
  return null;
}

// Función para procesar un mensaje de WhatsApp
function processMessage(message, contacts) {
  let result = { messageText: '', hasLocation: false, latitude: null, longitude: null };

  // Extraer info de contacto
  const contactInfo = extractContactInfo(contacts);
  if (contactInfo) {
    userName = contactInfo.userName;
    userId = contactInfo.wa_id;
    chatId = contactInfo.wa_id;
  }

  // Extraer ID del mensaje
  messageId = message.id || message.timestamp || Date.now();

  // Si el mensaje tiene from, usarlo
  if (message.from) {
    chatId = message.from;
    userId = message.from;
  }

  // DETECTAR TIPO DE MENSAJE
  const messageType = message.type || 'text';
  console.log('📨 Tipo de mensaje WhatsApp:', messageType);

  // UBICACIÓN
  if (messageType === 'location' || message.location) {
    result.hasLocation = true;
    result.latitude = message.location?.latitude || message.location?.lat;
    result.longitude = message.location?.longitude || message.location?.lon || message.location?.lng;
    result.messageText = `Fichar ubicacion: ${result.latitude}, ${result.longitude}`;
    console.log('📍 UBICACIÓN DETECTADA en WhatsApp:');
    console.log('   Latitud:', result.latitude);
    console.log('   Longitud:', result.longitude);
    console.log('   Mensaje generado:', result.messageText);
  }
  // TEXTO
  else if (message.text && message.text.body) {
    result.messageText = message.text.body;
  } else if (message.body) {
    result.messageText = message.body;
  } else if (messageType === 'text' && message.text?.body) {
    result.messageText = message.text.body;
  }

  return result;
}

